"""variables checkers for Python code
"""
import collections
import copy
import itertools
import os
import re
from functools import lru_cache
import astroid
from pylint.checkers import BaseChecker, utils
from pylint.checkers.utils import is_postponed_evaluation_enabled
from pylint.constants import PY39_PLUS
from pylint.interfaces import HIGH, INFERENCE, INFERENCE_FAILURE, IAstroidChecker
from pylint.utils import get_global_option
class VariablesChecker(BaseChecker):
    """checks for
    * unused variables / imports
    * undefined variables
    * redefinition of variable from builtins or from an outer scope
    * use of variable before assignment
    * __all__ consistency
    * self/cls assignment
    """

    def _has_homonym_in_upper_function_scope(self, node, index):
        """
        Return True if there is a node with the same name in the to_consume dict of an upper scope
        and if that scope is a function

        :param node: node to check for
        :type node: astroid.Node
        :param index: index of the current consumer inside self._to_consume
        :type index: int
        :return: True if there is a node with the same name in the to_consume dict of an upper scope
                 and if that scope is a function
        :rtype: bool
        """
        for _consumer in self._to_consume[index - 1 :: -1]:
            if _consumer.scope_type == "function" and node.name in _consumer.to_consume:
                return True
        return False

    def _store_type_annotation_node(self, type_annotation):
        """Given a type annotation, store all the name nodes it refers to"""
        if isinstance(type_annotation, astroid.Name):
            self._type_annotation_names.append(type_annotation.name)
            return

        if not isinstance(type_annotation, astroid.Subscript):
            return

        if (
            isinstance(type_annotation.value, astroid.Attribute)
            and isinstance(type_annotation.value.expr, astroid.Name)
            and type_annotation.value.expr.name == TYPING_MODULE
        ):
            self._type_annotation_names.append(TYPING_MODULE)
            return

        self._type_annotation_names.extend(
            annotation.name
            for annotation in type_annotation.nodes_of_class(astroid.Name)
        )

    def _store_type_annotation_names(self, node):
        type_annotation = node.type_annotation
        if not type_annotation:
            return
        self._store_type_annotation_node(node.type_annotation)

    def visit_import(self, node):
        """Mark imported names as used if they appear in type annotations."""
        for name, alias in node.names:
            if alias is None:
                alias = name
            if alias in self._type_annotation_names:
                self._mark_variable_as_used(node, alias)

    def visit_importfrom(self, node):
        """Mark imported names as used if they appear in type annotations."""
        for name, alias in node.names:
            if alias is None:
                alias = name
            if alias in self._type_annotation_names:
                self._mark_variable_as_used(node, alias)

    def _mark_variable_as_used(self, node, name):
        """Mark a variable as used."""
        if name in self._to_consume[-1].to_consume:
            del self._to_consume[-1].to_consume[name]

    def _check_unused_variables(self, node):
        """Check for unused variables in the current scope."""
        for name in self._to_consume[-1].to_consume:
            self.add_message('unused-variable', node=node, args=(name,))

    def _check_unused_imports(self, node):
        """Check for unused imports in the current scope."""
        for name in self._to_consume[-1].to_consume:
            self.add_message('unused-import', node=node, args=(name,))

    def leave_module(self, node):
        """Called when leaving a module. Perform final checks for unused imports and variables."""
        self._check_unused_imports(node)
        self._check_unused_variables(node)

    def visit_assign(self, node):
        """Handle assignment nodes, storing the assigned names in the current scope."""
        for target in node.targets:
            if isinstance(target, astroid.AssignName):
                self._to_consume[-1].to_consume[target.name] = node

    def visit_annassign(self, node):
        """Handle annotated assignment nodes, storing the assigned names in the current scope and
        storing the type annotation names.
        """
        self._to_consume[-1].to_consume[node.target.name] = node
        self._store_type_annotation_node(node.annotation)

    def visit_functiondef(self, node):
        """Handle function definitions, storing the function name and its parameters in the current scope.
        Also, store the type annotation names for the function's return type and parameters.
        """
        self._to_consume.append(Consumer(node, 'function'))
        for param in node.args.args:
            self._to_consume[-1].to_consume[param.name] = node
        if node.returns:
            self._store_type_annotation_node(node.returns)
        for default in node.args.defaults:
            if isinstance(default, astroid.Name):
                self._to_consume[-1].to_consume[default.name] = node
        for annotation in node.args.annotations:
            if annotation:
                self._store_type_annotation_node(annotation)

    def visit_classdef(self, node):
        """Handle class definitions, storing the class name and its attributes in the current scope.
        Also, store the type annotation names for the class's bases and decorators.
        """
        self._to_consume.append(Consumer(node, 'class'))
        for base in node.bases:
            if isinstance(base, astroid.Name):
                self._to_consume[-1].to_consume[base.name] = node
        for decorator in node.decorators:
            if isinstance(decorator, astroid.Name):
                self._to_consume[-1].to_consume[decorator.name] = node

    def visit_with(self, node):
        """Handle with statements, storing the assigned names in the current scope.
        """
        for item in node.items:
            if item[1]:
                self._to_consume[-1].to_consume[item[1].name] = node

    def visit_for(self, node):
        """Handle for loops, storing the assigned names in the current scope.
        """
        if isinstance(node.target, astroid.AssignName):
            self._to_consume[-1].to_consume[node.target.name] = node

    def visit_comprehension(self, node):
        """Handle comprehensions, storing the assigned names in the current scope.
        """
        if isinstance(node.target, astroid.AssignName):
            self._to_consume[-1].to_consume[node.target.name] = node

    def visit_tryexcept(self, node):
        """Handle try-except blocks, storing the assigned names in the current scope.
        """
        for handler in node.handlers:
            if handler.name:
                self._to_consume[-1].to_consume[handler.name] = node

    def visit_assignname(self, node):
        """Handle assignment names, storing them in the current scope.
        """
        self._to_consume[-1].to_consume[node.name] = node

    def visit_delname(self, node):
        """Handle deletion of names, removing them from the current scope.
        """
        if node.name in self._to_consume[-1].to_consume:
            del self._to_consume[-1].to_consume[node.name]

    def visit_name(self, node):
        """Handle name nodes, marking them as used if they are in the current scope.
        """
        if node.name in self._to_consume[-1].to_consume:
            del self._to_consume[-1].to_consume[node.name]

    def visit_attribute(self, node):
        """Handle attribute nodes, marking the base name as used if it is in the current scope.
        """
        if isinstance(node.expr, astroid.Name) and node.expr.name in self._to_consume[-1].to_consume:
            del self._to_consume[-1].to_consume[node.expr.name]

    def visit_yield(self, node):
        """Handle yield nodes, marking the yielded value as used if it is in the current scope.
        """
        if node.value and isinstance(node.value, astroid.Name) and node.value.name in self._to_consume[-1].to_consume:
            del self._to_consume[-1].to_consume[node.value.name]

    def visit_yieldfrom(self, node):
        """Handle yield from nodes, marking the yielded value as used if it is in the current scope.
        """
        if isinstance(node.value, astroid.Name) and node.value.name in self._to_consume[-1].to_consume:
            del self._to_consume[-1].to_consume[node.value.name]

    def visit_return(self, node):
        """Handle return nodes, marking the returned value as used if it is in the current scope.
        """
        if node.value and isinstance(node.value, astroid.Name) and node.value.name in self._to_consume[-1].to_consume:
            del self._to_consume[-1].to_consume[node.value.name]

    def visit_call(self, node):
        """Handle call nodes, marking the called function and its arguments as used if they are in the current scope.
        """
        if isinstance(node.func, astroid.Name) and node.func.name in self._to_consume[-1].to_consume:
            del self._to_consume[-1].to_consume[node.func.name]
        for arg in node.args:
            if isinstance(arg, astroid.Name) and arg.name in self._to_consume[-1].to_consume:
                del self._to_consume[-1].to_consume[arg.name]
        for keyword in node.keywords:
            if keyword.arg and keyword.arg in self._to_consume[-1].to_consume:
                del self._to_consume[-1].to_consume[keyword.arg]
            if keyword.value and isinstance(keyword.value, astroid.Name) and keyword.value.name in self._to_consume[-1].to_consume:
                del self._to_consume[-1].to_consume[keyword.value.name]

    def visit_subscript(self, node):
        """Handle subscript nodes, marking the base name as used if it is in the current scope.
