        if isinstance(node.value, astroid.Name) and node.value.name in self._to_consume[-1].to_consume:
            del self._to_consume[-1].to_consume[node.value.name]

    def visit_binop(self, node):
        """Handle binary operation nodes, marking the operands as used if they are in the current scope.
        """
        if isinstance(node.left, astroid.Name) and node.left.name in self._to_consume[-1].to_consume:
